<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { api } from './api';
import { suggestedTags, areas } from '../shared/catalog';
const tags = ref<string[]>([]), custom = ref(''), start = ref(''), end = ref(''), selected = ref(['Campus']);
const requests = ref<Array<{ request: string; status: string; start: number; end: number; reason: string }>>([]);
const error = ref(''), notice = ref(''), busy = ref(false), admin = ref(false), events = ref<Array<{ event: string; title: string; status: string }>>([]);
async function refresh() {
  const [profile, pool] = await Promise.all([api<{ profile: { interests: string } }>('/profile/mine'), api<{ pool: { requests: string } }>('/requests/mine')]);
  tags.value = JSON.parse(profile.profile.interests); requests.value = JSON.parse(pool.pool.requests);
  try { const result = await api<{ admin: { events: string } }>('/admin/events'); admin.value = true; events.value = JSON.parse(result.admin.events); } catch { admin.value = false; }
}
async function act(work: () => Promise<unknown>, message: string) {
  busy.value = true; error.value = ''; notice.value = '';
  try { await work(); await refresh(); notice.value = message; } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; }
}
function tag(value: string) { return act(() => api(tags.value.includes(value) ? '/profile/removeInterest' : '/profile/addInterest', { tag: value }), 'Interests saved.'); }
function submit() { return act(() => api('/requests/submit', { start: new Date(start.value).getTime(), end: new Date(end.value).getTime(), areas: JSON.stringify(selected.value) }), 'Your slot is in the pool. Matching runs hourly. Check your invitations for a match.'); }
onMounted(() => act(refresh, ''));
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">MAKE A LITTLE SPACE</p><h1>What are you up for?</h1><p>Choose your interests, then tell us when you're free.</p></div><button :disabled="busy" @click="act(refresh, '')">Refresh plans</button></div><p v-if="error" role="alert" class="notice">{{ error }}</p><p v-if="notice" role="status" class="notice">{{ notice }}</p>
<div class="planning-grid"><section class="panel"><h2>Your creative interests</h2><p class="hint">No experience needed. Pick up to 12.</p><div class="actions"><button v-for="item in [...new Set([...suggestedTags, ...tags])]" :key="item" :class="{ primary: tags.includes(item) }" :aria-pressed="tags.includes(item)" :disabled="busy" @click="tag(item)">{{ item }}</button></div><form class="custom-interest" @submit.prevent="tag(custom); custom = ''"><label>Something else?<input v-model="custom" maxlength="40" minlength="2" required placeholder="Your creative interest"></label><button :disabled="busy">Add interest</button></form></section>
<section class="panel"><h2>A little free time</h2><template v-if="requests.some(r => r.status !== 'CLOSED')"><article v-for="r in requests.filter(r => r.status !== 'CLOSED')" :key="r.request"><span class="tag">{{ r.status === 'OPEN' ? 'Waiting for a match' : 'Invitation ready' }}</span><p>{{ new Date(r.start).toLocaleString() }} – {{ new Date(r.end).toLocaleTimeString() }}</p><p>{{ r.status === 'OPEN' ? 'We’re looking for at least three people with shared interests, time, and area.' : 'Open Invitations to respond to your plan.' }}</p><button v-if="r.status === 'OPEN'" :disabled="busy" @click="act(() => api('/requests/withdraw', { request: r.request }), 'Slot withdrawn. You can choose a new time.')">Withdraw slot</button></article></template><form v-else @submit.prevent="submit"><p class="hint">Choose at least two hours on one day, at least 24 hours ahead. Times use {{ Intl.DateTimeFormat().resolvedOptions().timeZone }}.</p><label>Available from<input v-model="start" type="datetime-local" required></label><label>Available until<input v-model="end" type="datetime-local" required></label><fieldset><legend>Where could you meet?</legend><label v-for="area in areas" :key="area"><input v-model="selected" type="checkbox" :value="area">{{ area }}</label></fieldset><p v-if="!tags.length" class="hint">Choose an interest first.</p><button class="primary" :disabled="busy || !tags.length || !selected.length">Find me a JAM</button></form><details v-if="requests.some(r => r.status === 'CLOSED')"><summary>Previous slots</summary><p v-for="r in requests.filter(r => r.status === 'CLOSED')" :key="r.request">{{ new Date(r.start).toLocaleString() }} · {{ r.reason.replaceAll('_', ' ').toLowerCase() }}</p></details></section></div>
<section v-if="admin" class="panel admin-panel"><h2>Matching controls</h2><p>Run a matching round now, or let the hourly scheduler handle it.</p><button :disabled="busy" @click="act(() => api('/admin/run'), 'Matching round finished. Open Invitations to see matches.')">Run matching</button><article v-for="event in events" :key="event.event" class="admin-event"><b>{{ event.title }}</b> · {{ event.status }}<button v-if="['FORMING','CONFIRMED'].includes(event.status)" :disabled="busy" @click="act(() => api('/admin/cancel', { event: event.event }), 'Event cancelled without strikes. Eligible accepted requests are requeued.')">Cancel event</button></article></section></section></template>
